#include <iostream>
#include <vector>
#include <climits>
using namespace std;

int findSecondLargest(const vector<int>& arr) {
    long long first = LLONG_MIN, second = LLONG_MIN;
    for (int x : arr) {
        if (x > first) {
            second = first;
            first = x;
        } else if (x < first && x > second) {
            second = x;
        }
    }
    return (second == LLONG_MIN) ? -1 : (int)second;
}

