string normalizeName(const string& s) {
    stringstream ss(s);
    string word, result = "";
    while (ss >> word) {
        if (!word.empty()) {
            word[0] = toupper((unsigned char)word[0]);
            for (size_t i = 1; i < word.length(); ++i) {
                word[i] = tolower((unsigned char)word[i]);
            }
            if (!result.empty()) result += " ";
            result += word;
        }
    }
    return result;
}

int main() {
    string s;
    if (getline(cin, s)) {
        cout << normalizeName(s) << endl;
    }
    return 0;
