int main() {
    int n;
    if (!(cin >> n) || n <= 0) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    // Boyer-Moore Voting Algorithm
    int candidate = a[0], count = 1;
    for (int i = 1; i < n; ++i) {
        if (a[i] == candidate) {
            count++;
        } else {
            count--;
            if (count == 0) {
                candidate = a[i];
                count = 1;
            }
        }
    }

    // Xác minh lại
    int freq = 0;
    for (int x : a) {
        if (x == candidate) freq++;
    }

    if (freq > n / 2) {
        cout << candidate << endl;
    } else {
        cout << "NO" << endl;
    }
    return 0;
}

