#include <iostream>
#include <cstring>
using namespace std;

void reverseWithPointer(char* s) {
    if (!s) return;
    char* start = s;
    char* end = s + strlen(s) - 1;
    while (start < end) {
        char temp = *start;
        *start = *end;
        *end = temp;
        start++;
        end--;
    }
}

int main() {
    char s[1005];
    if (cin.getline(s, 1005)) {
        reverseWithPointer(s);
        cout << s << endl;
    }
    return 0;
