    int topIdx = 0;
    float maxGpa = -1.0f;

    for (int i = 0; i < n; ++i) {
        string line;
        if (!getline(cin, line)) break;
        stringstream ss(line);
        Student s;
        ss >> s.id;
        string temp;
        vector<string> nameParts;
        float g;
        while (ss >> temp) {
            try {
                size_t idx;
                g = stof(temp, &idx);
                if (idx == temp.length()) {
                    s.gpa = g;
                    break;
                } else {
                    nameParts.push_back(temp);
                }
            } catch (...) {
                nameParts.push_back(temp);
            }
        }
        string full = "";
        for (size_t k = 0; k < nameParts.size(); ++k) {
