#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
using namespace std;

class SinhVien {
private:
    string id, name;
    double gpa;
public:
    SinhVien(string id, string name, double gpa) : id(id), name(name), gpa(gpa) {}
    double getGpa() const { return gpa; }
};

class LopHoc {
private:
    vector<SinhVien> ds;
public:
    void themSV(const SinhVien& sv) { ds.push_back(sv); }

    double tinhDiemTB() const {
        if (ds.empty()) return 0;
        double sum = 0;
        for (const auto& s : ds) sum += s.getGpa();
        return sum / ds.size();
    }

    int demGioi() const {
        int cnt = 0;
        for (const auto& s : ds) {
            if (s.getGpa() >= 8.0) cnt++;
        }
        return cnt;
    }
};

int main() {
    int n;
    if (!(cin >> n)) return 0;
    LopHoc lop;
    for (int i = 0; i < n; ++i) {
        string id, name;
        double gpa;
        cin >> id >> name >> gpa;
        lop.themSV(SinhVien(id, name, gpa));
    }
    cout << "GPA TB: " << fixed << setprecision(2) << lop.tinhDiemTB() << "\n";
    cout << "SO SV GIOI: " << lop.demGioi() << endl;
    return 0;
}

